$('markContact').onclick=()=>{const scale=statsFor(attacker).timing;const startup=Math.round(frame/scale);if(startup>180){status('Impact must fit within 180 authored startup frames. Scrub earlier or shorten the path.');return;}attack().impactTrigger='timed';attack().startup=startup;changed();renderSettings();status('Impact begins at simulation frame '+simulation.timing.startup+'. Pre-impact loops release here.');};

