function ensureAllSkins(explicit=false){
 if(!explicit)return;
 if(!library||!attack()||attack().reskinGroupId)return;
 const current=attack(),next=ensureReskinGroup(project.attacks,current,library.effects,()=>freshAttack().id);
 if(next!==project.attacks){const updated=next.find(a=>a.id===current.id);Object.assign(current,updated);project.attacks=next.map(a=>a.id===current.id?current:a);dirty=true;refreshDrafts();}
}
function renderReskinGroup(){
 const root=$('reskinGroup');if(!root||!library||!attack())return;root.replaceChildren();const a=attack(),members=groupMembers(project.attacks,a);
 const note=document.createElement('p');note.className='hint';
 note.textContent=a.reskinGroupId?`Applies to all ${members.length} skins automatically. Edit this attack once: damage, hitbox, movement, timing and frames update every matching skin. Save attack saves them all. Each keeps its artwork and element.`:'Adding artwork keeps this attack independent. Create a linked elemental family explicitly to share behavior across matching skins.';
 root.append(note);if(!a.reskinGroupId){const create=document.createElement('button');create.textContent='Create linked elemental family';create.onclick=()=>{ensureAllSkins(true);changed();refresh();};root.append(create);}$('saveAttack').textContent='Save attack to bank';
}

$('moveTarget').onclick=()=>{editMode='target';playing=false;frame=0;recompute();status('Click or drag in the viewer to place the target’s feet. Move it sideways or up for aerial tests.');};

$('markOpponentImpact').onclick=()=>{attack().impactTrigger='contact';configureContactLoops();frame=0;playing=false;changed();renderSettings();renderLayers();status('Impact on touch enabled. Each test waits for opponent contact; moving the target automatically changes when impact happens.');};


function configureContactLoops(){if(attack().impactTrigger!=='contact')return;for(const v of attack().visuals){if(v.loopUntilImpact)continue;const e=effectMap.get(v.effectId);if(!e)continue;const impact=v.frames?Math.max(1,v.frames.indexOf(e.impact-1)+1):(e.impact||e.times.length);v.loopUntilImpact=true;v.loopStart=1;v.loopEnd=Math.max(1,impact-1);}}

function openReskinStarter(effect){try{const members=createReskinStarter(effect,library.effects);if(project.attacks.length+members.length>256)throw Error('This workspace is full. Download your project and open a smaller workspace before adding another family.');project.attacks.push(...members);selected=members[0].id;frame=0;playing=false;dirty=true;refresh();status('Opened '+members.length+' elemental starters with stats and paths. Edit any member, then Save attack to keep the family. Existing drafts were preserved.');}catch(e){status(e.message);}}
$('openReskinStarter').onclick=()=>openReskinStarter(effectMap.get($('reskinStarter').value));

function openTunedAttack(effectId){try{const setup=reviewedSetups.get(effectId);if(!setup)throw Error('This attack has not completed individual tuning yet.');const members=openReviewedAttack(setup,library.effects);if(project.attacks.length+members.length>256)throw Error('The workspace is full. Download your project before opening more attacks.');project.attacks.push(...members);selected=members[0].id;frame=0;playing=false;dirty=true;refresh();status('Opened tuned '+setup.attack.name+' as a new editable copy. Existing drafts were preserved.');}catch(e){status(e.message);}}
$('openTunedAttack').onclick=()=>openTunedAttack($('tunedAttack').value);

function recordEdit(){
 project.version=attacksVersion(project.attacks);
 if(!history||restoringHistory)return;
 const key=drag?'drag:'+drag.kind:document.activeElement?.dataset.field||'';
 if(history.record(project,key?selected+':'+key:'')){
  dirty=true;clearTimeout(recoveryTimer);$('saveState').textContent='Unsaved changes · recovery pending';
  recoveryTimer=setTimeout(()=>{try{validateDesign(project,ids);localStorage.setItem(storageKey+'-recovery',JSON.stringify(project));$('saveState').textContent='Draft recovered locally · classroom bank unchanged';}catch(e){$('saveState').textContent='Recovery unavailable · download a backup';}},300);
 }
 $('undo').disabled=!history.past.length;$('redo').disabled=!history.future.length;
}
function restoreEdit(direction){
 const next=history?.[direction]();if(!next)return;
 restoringHistory=true;project=next;if(!project.attacks.some(a=>a.id===selected))selected=project.attacks[0].id;
 connectTestBench();installSandbox();playing=false;frame=0;refresh();restoringHistory=false;dirty=true;
 try{localStorage.setItem(storageKey+'-recovery',JSON.stringify(project));$('saveState').textContent='Restored edit · recovery saved locally';}catch{}
 recordEdit();
}
